"use server";

import { revalidatePath } from "next/cache";
import { getNotificationsEnabled, setNotificationsEnabled } from "./store";

export async function toggleNotificationPreference() {
  const current = getNotificationsEnabled();
  setNotificationsEnabled(!current);
  revalidatePath("/");
}

