import { toggleNotificationPreference } from "./actions";
import { getNotificationsEnabled } from "./store";

export default function Home() {
  const enabled = getNotificationsEnabled();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently: <strong>{enabled ? "ON" : "OFF"}</strong>
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn {enabled ? "OFF" : "ON"}
        </button>
      </form>
    </main>
  );
}

